(function(root){
  'use strict';
  // Read completed sessions only. Current drafts and prescribed ranges are not results.
  function read(state,plan,day,exercise){
    if(!plan||!day||!exercise)return null;
    const records=(Array.isArray(state.workoutExecutions)?state.workoutExecutions:[])
      .filter(r=>r&&r.studentId===plan.studentId&&r.planId===plan.id&&r.dayId===day.id&&Array.isArray(r.exercises)&&r.exercises.some(e=>e?.exerciseId===exercise.id))
      .slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.finishedAt||b.recordedAt||'').localeCompare(String(a.finishedAt||a.recordedAt||''))||String(b.id||'').localeCompare(String(a.id||'')));
    const record=records[0];if(!record)return null;
    const entry=record.exercises.find(e=>e?.exerciseId===exercise.id),values=Object.create(null),units=Object.create(null);
    for(const row of Array.isArray(entry.performedSets)?entry.performedSets:[]){
      const timed=row?.unit==='seconds'||root.APTimedSeries?.isTimed(row?.prescribedReps)===true,round=Number(row?.round),reps=Number(timed?row.seconds??row.reps:row?.reps);
      if(row&&row.done!==false&&Number.isInteger(round)&&round>=1&&round<=100&&Number.isInteger(reps)&&reps>=1&&reps<=(timed?86400:999)){values[round]=reps;units[round]=timed?'seconds':'reps';}
    }
    // Missing rounds in a partial session remain blank; never mix two sessions.
    return {date:String(record.date||''),recordId:record.id,values,units};
  }
  root.APWorkoutPreviousSeries=Object.freeze({read});
})(window);

(function(){
  'use strict';

  const allCatalogItems = workoutCatalogItems;
  const resolveVideo = workoutExerciseVideoUrl;
  const resolveGuidance = withWorkoutGuidance;
  const recoverVideos = recoverWorkoutGalleryVideos;
  const catalogChanges = workoutCatalogChanges;
  const fillFields = fillWorkoutExerciseFields;
  const field = suffix => document.getElementById('workoutExercise' + suffix);
  let includeRemoved = false;

  // Fichas antigas podem resolver demonstração e instruções pelo catálogo.
  function withRemoved(read, args) {
    const previous = includeRemoved;
    includeRemoved = true;
    try {
      return read(...args);
    } finally {
      includeRemoved = previous;
    }
  }

  const removed = item => item.catalogRemoved === true;
  const refersTo = (exercise, item) =>
    exercise.catalogId === item.id || workoutCatalogSameName(exercise, item);

  workoutCatalogItems = function(){
    const items = allCatalogItems();
    return includeRemoved ? items : items.filter(item => !removed(item));
  };
  workoutExerciseVideoUrl = (...args) => withRemoved(resolveVideo, args);
  withWorkoutGuidance = (...args) => withRemoved(resolveGuidance, args);
  recoverWorkoutGalleryVideos = (...args) => withRemoved(recoverVideos, args);

  workoutCatalogChanges = function(exercise){
    if (workoutExerciseMode !== 'catalog') {
      const selectedId = field('CatalogId').value;
      const selected = workoutCatalogItem(selectedId);
      const prior = !selected && allCatalogItems().find(item => removed(item) && refersTo({...exercise, catalogId: selectedId}, item));
      if (prior) return {catalogId: selectedId || prior.id, changes: {}};
    }
    return catalogChanges(exercise);
  };

  const favorite = field('Favorite').closest('label');
  const row = document.createElement('div');
  row.className = 'field full ap-catalog-delete-row';
  const button = document.createElement('button');
  button.type = 'button';
  button.id = 'workoutCatalogDelete';
  button.className = 'btn danger';
  button.textContent = 'Apagar exercício';
  button.hidden = true;
  favorite.before(row);
  row.append(favorite, button);

  const style = document.createElement('style');
  style.textContent = `
    #workoutExerciseForm .ap-catalog-delete-row:not(.has-catalog-delete) { display: contents; }
    #workoutExerciseForm .ap-catalog-delete-row.has-catalog-delete {
      display: flex; flex-wrap: wrap; align-items: center;
      justify-content: space-between; gap: 4px 12px;
    }
    .ap-catalog-delete-row > .workout-toggle { min-width: 0; }
    #workoutCatalogDelete { margin-inline-start: auto; min-height: 44px; }
    #workoutCatalogDelete[hidden] { display: none !important; }
  `;
  document.head.append(style);

  fillWorkoutExerciseFields = function(...args){
    fillFields(...args);
    const canDelete = workoutExerciseMode === 'catalog' && !!workoutCatalogItem(field('CatalogId').value);
    button.hidden = !canDelete;
    row.classList.toggle('has-catalog-delete', canDelete);
  };

  function removeCatalogItem(catalogId, fromEditor = false) {
    const item = workoutCatalogItem(catalogId);
    if (!item || !confirm('Apagar “' + item.name + '” da lista de exercícios? As fichas já montadas e o histórico serão preservados.')) return;

    const inUse = state.workoutPlans.some(plan => plan.days.some(day =>
      day.exercises.some(exercise => refersTo(exercise, item))
    ));
    const changes = {exerciseFavorites: state.exerciseFavorites.filter(id => id !== item.id)};
    if (item.source === 'app') {
      const original = state.exerciseCatalogOverrides[item.id];
      const record = inUse ? original : null;
      changes.exerciseCatalogOverrides = {
        ...state.exerciseCatalogOverrides,
        [item.id]: {...record, catalogRemoved: true}
      };
    } else {
      changes.exerciseCatalog = inUse
        ? state.exerciseCatalog.map(exercise => exercise.id === item.id ? {...exercise, catalogRemoved: true} : exercise)
        : state.exerciseCatalog.filter(exercise => exercise.id !== item.id);
    }

    if (!commitWorkoutChange(changes, '', false)) return;
    if (fromEditor) closeDialog('workoutExerciseDialog');
    renderWorkoutCatalog();
    toast('Exercício removido do catálogo.');
  }

  deleteCatalogExercise = removeCatalogItem;
  button.addEventListener('click', () => {
    if (workoutExerciseMode === 'catalog' && document.getElementById('workoutExerciseDialog').classList.contains('open')) {
      removeCatalogItem(field('CatalogId').value, true);
    }
  });
})();
